#' Bottle opening stability
#'
#' 
#' @param data .
#' @param x .
#' @param y .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$bos} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$t} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$sb1} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$b1} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$s} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$xi} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$xm} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' @export
BOS <- function(
    data,
    x,
    y) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("BOS requires jmvcore to be installed (restart may be required)")

    if ( ! missing(x)) x <- jmvcore::resolveQuo(jmvcore::enquo(x))
    if ( ! missing(y)) y <- jmvcore::resolveQuo(jmvcore::enquo(y))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(x), x, NULL),
            `if`( ! missing(y), y, NULL))


    options <- BOSOptions$new(
        x = x,
        y = y)

    analysis <- BOSClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

